const CHANNEL_NAME = 'app-state-sync';

type Message<T> = { type: string; payload: T };

function useCrossTabSync<T>(onMessage: (payload: T) => void) {
  useEffect(() => {
    const channel = new BroadcastChannel(CHANNEL_NAME);
    channel.onmessage = (event: MessageEvent<Message<T>>) => {
      onMessage(event.message.payload);
    };
    return () => channel.close();
  }, [onMessage]);
}

function ThemeSyncProvider({ children }: { children: ReactNode }) {
  const [theme, setTheme] = useState<'light' | 'dark'>('light');

  useCrossTabSync<{ theme: 'light' | 'dark' }>((payload) => {
    setTheme(payload.theme);
  });

  const toggleTheme = () =>
    setTheme((prev) => {
      const next = prev === 'light' ? 'dark' : 'light';
      localStorage.setItem('theme', next);
      window.dispatchEvent(new CustomEvent('app-theme-changed', { detail: next }));
      return next;
    });

  return (
    <ThemeContext.Provider value={{ theme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
}

function useSyncedTheme() {
  const [theme, setTheme] = useState(() =>
    (localStorage.getItem('theme') as 'light' | 'dark') ?? 'light'
  );

  useEffect(() => {
    const handler = (event: StorageEvent) => {
      if (event.key === 'theme' && event.newValue) {
        setTheme(event.newValue as 'light' | 'dark');
      }
    };
    window.addEventListener('storage', handler);
    return () => window.removeEventListener('storage', handler);
  }, []);

  const toggle = () => {
    const next = theme === 'light' ? 'dark' : 'light';
    setTheme(next);
    localStorage.setItem('theme', next);
  };

  return { theme, toggle };
}
